    // ── State ──
    private string _maTruongBo = "";
    private string _tenTruong  = "Trường học";
    private string _namHoc     = "2025-2026";

    private bool _isLoading   = false;
    private bool _isSaving    = false;
    private bool _isUploading = false;

    // ── Data ──
    private List<BaoBaiDTO>   _allList            = new();
    private List<LopHoc_DTO>  _danhSachLop        = new();
    private List<HocSinhDTO>  _danhSachHsSuggestion = new();

    // ── Filters ──
    private string _searchTextVal  = "";
    private int    _filterLopIdVal = 0;

    private string _searchText
    {
        get => _searchTextVal;
        set { _searchTextVal = value; _currentPage = 1; BuildPagedList(); }
    }

    private int _filterLopId
    {
        get => _filterLopIdVal;
        set { _filterLopIdVal = value; _currentPage = 1; BuildPagedList(); }
    }

    // ── Pagination ──
    private int _currentPage = 1;
    private int _pageSize    = 15;
    private List<BaoBaiDTO> _filteredList = new();
    private List<BaoBaiDTO> _pagedList    = new();
    private readonly int[] _pageSizeOptions = new[] { 10, 15, 25, 50 };

    // ── Compose ──
    private bool      _showComposeModal = false;
    private BaoBaiDTO _editDto          = new();
    private string    _composeError     = "";
    private string    _uploadError      = "";

    // ── Delete ──
    private bool       _showDeleteConfirm = false;
    private BaoBaiDTO? _deleteTarget;

    // ── View ──
    private BaoBaiDTO? _viewTarget;

    // ── Toast ──
    private string _toastMsg     = "";
    private string _toastType    = "success";
    private bool   _toastVisible = false;
    private System.Threading.CancellationTokenSource? _toastCts;

    // ── Lifecycle ──
    protected override async Task OnInitializedAsync()
    {
        _maTruongBo = await BrowserStorageService.GetMaTruongBoAsync(JS);
        _tenTruong  = await BrowserStorageService.GetItem(JS, "tenTruong") ?? "Trường học";
        await LoadAll();
    }

    private async Task LoadAll()
    {
        _isLoading = true;
        StateHasChanged();
        try
        {
            await Task.WhenAll(LoadBaoBai(), LoadDanhMuc());
        }
        finally
        {
            _isLoading = false;
            StateHasChanged();
        }
    }

    private async Task LoadBaoBai()
    {
        try
        {
            _allList = await ThongBaoServices.hGetDanhSachBaoBai(_maTruongBo);
            BuildPagedList();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"LoadBaoBai error: {ex.Message}");
            await ShowToast("Lỗi tải danh sách báo bài!", "error");
        }
    }

    private async Task LoadDanhMuc()
    {
        try
        {
            _danhSachLop = await TruongService.hGetDanhSachLop(_maTruongBo, "", _namHoc);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"LoadDanhMuc error: {ex.Message}");
        }
    }

    // ── Pagination ──
    private void BuildPagedList()
    {
        _filteredList = _allList
            .Where(x => _filterLopIdVal == 0 || x.lopid == _filterLopIdVal)
            .Where(x => string.IsNullOrEmpty(_searchTextVal) ||
                        (x.noidung?.Contains(_searchTextVal, StringComparison.OrdinalIgnoreCase) == true) ||
                        (x.nguoi_gui?.Contains(_searchTextVal, StringComparison.OrdinalIgnoreCase) == true))
            .OrderByDescending(x => x.ngaytao ?? DateTime.MinValue)
            .ToList();

        _pagedList = _filteredList
            .Skip((_currentPage - 1) * _pageSize)
            .Take(_pageSize)
            .ToList();
    }

    private void OnPageChanged(int page)
    {
        _currentPage = page;
        _pagedList = _filteredList
            .Skip((_currentPage - 1) * _pageSize)
            .Take(_pageSize)
            .ToList();
        StateHasChanged();
    }

    private void OnPageSizeChanged(int size)
    {
        _pageSize    = size;
        _currentPage = 1;
        BuildPagedList();
        StateHasChanged();
    }

    // ── Helpers ──
    private string GetTenLop(int lopId)
    {
        var lop = _danhSachLop.FirstOrDefault(l => l.IdLopBo == lopId);
        return lop?.TenLop ?? (lopId > 0 ? $"Lớp {lopId}" : "—");
    }

    private string GetTenHocSinh(string maHs)
    {
        var hs = _danhSachHsSuggestion.FirstOrDefault(h => h.MaHsSo == maHs);
        return hs?.HoTen ?? maHs;
    }

    private string GetFileName(string? filepath)
    {
        if (string.IsNullOrEmpty(filepath)) return "";
        return filepath.Split('/').LastOrDefault() ?? filepath;
    }

    private void ClearFilepath() => _editDto.filepath = string.Empty;

    // ── Lọc HS theo lớp khi tạo bài ──
    private async Task OnLopChanged()
    {
        _danhSachHsSuggestion = new();
        _editDto.id_hoc_sinh  = "";
        if (_editDto.lopid <= 0) return;

        var lop = _danhSachLop.FirstOrDefault(l => l.IdLopBo == _editDto.lopid);
        if (lop == null) return;
        try
        {
            _danhSachHsSuggestion = await TruongService.hGetHocSinhByLop(_maTruongBo, lop.MaLopBo, _namHoc);
        }
        catch { _danhSachHsSuggestion = new(); }
        StateHasChanged();
    }

    // ── Open/Close modal ──
    private void OpenCompose()
    {
        _editDto = new BaoBaiDTO { ma_truong_bo = _maTruongBo, ngaytao = DateTime.Now };
        _danhSachHsSuggestion = new();
        _composeError = "";
        _uploadError  = "";
        _showComposeModal = true;
    }

    private void OpenEdit(BaoBaiDTO item)
    {
        _viewTarget = null;
        _editDto = new BaoBaiDTO
        {
            id_chude      = item.id_chude,
            noidung       = item.noidung,
            lopid         = item.lopid,
            id_hoc_sinh   = item.id_hoc_sinh,
            nguoi_gui     = item.nguoi_gui,
            filepath      = item.filepath,
            ngaytao       = item.ngaytao,
            ngayketthuc   = item.ngayketthuc,
            ma_truong_bo  = _maTruongBo,
        };
        _composeError = "";
        _uploadError  = "";
        _showComposeModal = true;
        // Tải lại HS cho lớp hiện tại
        _ = OnLopChanged();
    }

    private void OpenView(BaoBaiDTO item) => _viewTarget = item;
    private void CloseComposeModal() => _showComposeModal = false;

    // ── Save ──
    private async Task SaveBaoBai()
    {
        _composeError = "";

        if (_editDto.lopid <= 0)
        { _composeError = "Vui lòng chọn lớp!"; return; }
        if (string.IsNullOrWhiteSpace(_editDto.noidung))
        { _composeError = "Vui lòng nhập nội dung bài tập!"; return; }

        _isSaving = true;
        StateHasChanged();
        try
        {
            bool isNew = string.IsNullOrEmpty(_editDto.id_chude);
            bool ok;
            if (isNew)
            {
                _editDto.ngaytao = DateTime.Now;
                ok = await ThongBaoServices.hInsertBaoBai(_editDto);
            }
            else
            {
                ok = await ThongBaoServices.hUpdateBaoBai(_editDto);
            }

            if (ok)
            {
                _showComposeModal = false;
                await LoadBaoBai();
                await ShowToast(isNew ? "Đã giao bài thành công!" : "Đã cập nhật báo bài!", "success");
            }
            else
            {
                _composeError = "Lưu thất bại, vui lòng thử lại!";
            }
        }
        catch (Exception ex)
        {
            _composeError = "Đã xảy ra lỗi, vui lòng thử lại!";
        }
        finally
        {
            _isSaving = false;
            StateHasChanged();
        }
    }

    // ── Delete ──
    private void AskDelete(BaoBaiDTO item)
    {
        _viewTarget   = null;
        _deleteTarget = item;
        _showDeleteConfirm = true;
    }

    private void CloseDeleteConfirm()
    {
        _showDeleteConfirm = false;
        _deleteTarget      = null;
    }

    private async Task ExecuteDelete()
    {
        if (_deleteTarget == null) return;
        _isSaving = true;
        StateHasChanged();
        try
        {
            bool ok = await ThongBaoServices.hDeleteBaoBai(_deleteTarget.id_chude, _maTruongBo);
            _showDeleteConfirm = false;
            _deleteTarget = null;
            if (ok)
            {
                await LoadBaoBai();
                await ShowToast("Đã xóa báo bài!", "success");
            }
            else
            {
                await ShowToast("Xóa thất bại!", "error");
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"ExecuteDelete error: {ex.Message}");
            await ShowToast("Xóa thất bại!", "error");
        }
        finally
        {
            _isSaving = false;
            StateHasChanged();
        }
    }

    // ── File Upload (giống TB_QuanLyThongBao) ──
    private async Task OnFileSelected(InputFileChangeEventArgs e)
    {
        _uploadError = "";
        var file = e.File;
        if (file == null) return;
        if (file.Size > 20 * 1024 * 1024)
        {
            _uploadError = "File quá lớn! Tối đa 20MB.";
            StateHasChanged();
            return;
        }

        _isUploading = true;
        StateHasChanged();

        try
        {
            using var ms = new System.IO.MemoryStream();
            await file.OpenReadStream(maxAllowedSize: 20 * 1024 * 1024).CopyToAsync(ms);
            ms.Position = 0;

            var client  = HttpClientFactory.CreateClient();
            var content = new MultipartFormDataContent();
            var byteContent = new ByteArrayContent(ms.ToArray());
            byteContent.Headers.ContentType = new System.Net.Http.Headers.MediaTypeHeaderValue(file.ContentType);
            content.Add(byteContent, "file", file.Name);

            string url = $"https://nhatkyhoatdong.titkul.edu.vn/upload/media/{_maTruongBo}";
            var response = await client.PostAsync(url, content);

            if (response.IsSuccessStatusCode)
            {
                var json = await response.Content.ReadAsStringAsync();
                using var doc = System.Text.Json.JsonDocument.Parse(json);
                var root = doc.RootElement;
                if (root.TryGetProperty("error", out var errProp) && errProp.GetInt32() == 0)
                {
                    var urls = root.GetProperty("data").GetProperty("urls");
                    _editDto.filepath = urls[0].GetString() ?? "";
                    await ShowToast("Tải file lên thành công!", "success");
                }
                else
                {
                    _uploadError = "Server báo lỗi khi upload file!";
                }
            }
            else
            {
                _uploadError = $"Upload thất bại! HTTP {(int)response.StatusCode}";
            }
        }
        catch (Exception ex)
        {
            _uploadError = "Đã xảy ra lỗi, vui lòng thử lại!";
        }
        finally
        {
            _isUploading = false;
            StateHasChanged();
        }
    }

    // ── Toast ──
    private async Task ShowToast(string msg, string type = "success")
    {
        _toastCts?.Cancel();
        _toastCts     = new System.Threading.CancellationTokenSource();
        _toastMsg     = msg;
        _toastType    = type;
        _toastVisible = true;
        StateHasChanged();
        try
        {
            await Task.Delay(3500, _toastCts.Token);
            _toastVisible = false;
            StateHasChanged();
        }
        catch (TaskCanceledException) { }
    }

